159	// detectTimezone returns a best-effort timezone name for the current host.
160	// Order: $TZ → /etc/localtime symlink → time.Local → "UTC" as last resort.
161	// A candidate that fails normalization is skipped (not forwarded, not coerced
162	// to UTC), so a bogus $TZ on a correctly-configured box still yields the
163	// system timezone from /etc/localtime. The server is the canonical authority
164	// for what counts as a valid zone and falls back to UTC for anything it
165	// doesn't recognize, so we only do enough validation to avoid sending
166	// obvious garbage (paths, POSIX forms Go can't load, the "Local" sentinel).
167	func detectTimezone() string {
168		if tz := normalizeTimezone(os.Getenv("TZ")); tz != "" {
169			return tz
170		}
